#include <bits/stdc++.h>
using namespace std; using B=bitset<512>;
struct F{B s;int d;};struct N{bool fixed;int f;vector<int> regs,pre,nxt;};
vector<F> fs;vector<N> ns;long double pc[10];
bool sub(int a,int b){return (fs[a].s & ~fs[b].s).none();}
long double change(const vector<int>&v,int f){unordered_set<int>S(v.begin(),v.end());long double z=0;for(int i:v){auto &n=ns[i];for(int j:n.pre)if(j>=0&&!S.count(j)){z+=pc[fs[f].d-fs[ns[j].f].d]-pc[fs[n.f].d-fs[ns[j].f].d];}for(int j:n.nxt)if(j>=0&&!S.count(j)){z+=pc[fs[ns[j].f].d-fs[f].d]-pc[fs[ns[j].f].d-fs[n.f].d];}}return z;}
int main(int argc,char**argv){ifstream in(argv[1]);int nf,nn,nr;in>>nf>>nn>>nr;fs.resize(nf);ns.resize(nn);for(auto &f:fs){int n,x;in>>n;f.d=round(log2(n));while(n--){in>>x;f.s[x]=1;}}vector<int>last(nr,-1);for(int i=0;i<nn;i++){auto &n=ns[i];int fixed,k;in>>fixed>>n.f>>k;n.fixed=fixed;while(k--){int r;in>>r;n.regs.push_back(r);n.pre.push_back(last[r]);n.nxt.push_back(-1);if(last[r]>=0){auto &p=ns[last[r]];int j=find(p.regs.begin(),p.regs.end(),r)-p.regs.begin();p.nxt[j]=i;}last[r]=i;}}
for(int d=1;d<10;d++)pc[d]=powl(d,1-.001594L);vector<int>orig;for(auto &n:ns)orig.push_back(n.f);mt19937 rng(20261011);int accepted=0;long double gain=0;
auto trygroup=[&](vector<int>v){unordered_set<int>S(v.begin(),v.end());vector<int>lo,hi;for(int i:v){for(int j:ns[i].pre)if(j>=0&&!S.count(j))lo.push_back(ns[j].f);for(int j:ns[i].nxt)if(j>=0&&!S.count(j))hi.push_back(ns[j].f);}int best=-1;long double bestdelta=-1e-13L;for(int f=0;f<nf;f++){bool ok=true;for(int l:lo)if(!sub(l,f)){ok=false;break;}if(!ok)continue;for(int h:hi)if(!sub(f,h)){ok=false;break;}if(!ok)continue;long double d=change(v,f);if(d<bestdelta){bestdelta=d;best=f;}}if(best<0)return false;for(int i:v)ns[i].f=best;gain-=bestdelta;accepted++;return true;};
for(int round=0;round<10;round++){int start=accepted;vector<int>ord(nn);iota(ord.begin(),ord.end(),0);shuffle(ord.begin(),ord.end(),rng);for(int i:ord)if(!ns[i].fixed)trygroup({i});vector<int>seen(nn);for(int i:ord)if(!seen[i]&&!ns[i].fixed){vector<int>v{i};seen[i]=1;for(int k=0;k<(int)v.size();k++){int t=v[k];vector<int>adj=ns[t].pre;adj.insert(adj.end(),ns[t].nxt.begin(),ns[t].nxt.end());for(int j:adj)if(j>=0&&!seen[j]&&!ns[j].fixed&&ns[j].f==ns[i].f){seen[j]=1;v.push_back(j);}}if(v.size()>1)trygroup(v);}cerr<<round<<" accepted "<<accepted<<" gain "<<setprecision(18)<<gain<<"\n";if(start==accepted)break;}
map<int,int>oldh,newh;for(int i=0;i<nn;i++)for(int j:ns[i].pre)if(j>=0){int o=fs[orig[i]].d-fs[orig[j]].d,n=fs[ns[i].f].d-fs[ns[j].f].d;assert(sub(ns[j].f,ns[i].f));if(o)oldh[o]++;if(n)newh[n]++;}ofstream out(argv[2]);out<<"{\"changes\":[";bool first=true;for(int i=0;i<nn;i++)if(orig[i]!=ns[i].f){if(!first)out<<",";first=false;out<<"["<<i<<","<<ns[i].f<<"]";}out<<"],\"delta\":{";first=true;for(int d=1;d<10;d++)if(newh[d]!=oldh[d]){if(!first)out<<",";first=false;out<<"\""<<d<<"\":"<<newh[d]-oldh[d];}out<<"},\"accepted_groups\":"<<accepted<<"}\n";}
